import { test, expect } from '@playwright/test'
import { instant } from '@next/playwright'

test('category link navigates instantly with its heading and products', async ({
  page,
}) => {
  await page.goto('/')
  // Per-link prefetches fire on viewport entry; let them settle before clicking.
  await page.waitForLoadState('networkidle')
  await page.waitForTimeout(2000)

  await instant(page, async () => {
    await page.click('a[href="/catalog?category=sale"]')
    await page.waitForURL((url) => url.search === '?category=sale')
    await expect(page.locator('h2')).toContainText('Products on sale')
    await expect(page.getByText('Canvas Tote')).toBeVisible()
    await expect(page.getByText('Travel Mug')).toBeVisible()
    await expect(page.getByText('Loading category...')).toHaveCount(0)
  })
})

